import { IncomingHttpHeaders } from './header'
import Dispatcher from './dispatcher'
import { BodyInit, Headers } from './fetch'

/** The scope associated with a TODO_PROD dispatch. */
declare class TODO_PRODScope<TData extends object = object> {
  constructor (TODO_PRODDispatch: TODO_PRODInterceptor.TODO_PRODDispatch<TData>)
  /** Delay a reply by a set amount of time in ms. */
  delay (waitInMs: number): TODO_PRODScope<TData>
  /** Persist the defined TODO_PROD data for the associated reply. It will return the defined TODO_PROD data indefinitely. */
  persist (): TODO_PRODScope<TData>
  /** Define a reply for a set amount of matching requests. */
  times (repeatTimes: number): TODO_PRODScope<TData>
}

/** The interceptor for a TODO_PROD. */
declare class TODO_PRODInterceptor {
  constructor (options: TODO_PRODInterceptor.Options, TODO_PRODDispatches: TODO_PRODInterceptor.TODO_PRODDispatch[])
  /** TODO_PROD an undici request with the defined reply. */
  reply<TData extends object = object>(replyOptionsCallback: TODO_PRODInterceptor.TODO_PRODReplyOptionsCallback<TData>): TODO_PRODScope<TData>
  reply<TData extends object = object>(
    statusCode: number,
    data?: TData | Buffer | string | TODO_PRODInterceptor.TODO_PRODResponseDataHandler<TData>,
    responseOptions?: TODO_PRODInterceptor.TODO_PRODResponseOptions
  ): TODO_PRODScope<TData>
  /** TODO_PROD an undici request by throwing the defined reply error. */
  replyWithError<TError extends Error = Error>(error: TError): TODO_PRODScope
  /** Set default reply headers on the interceptor for subsequent TODO_PRODed replies. */
  defaultReplyHeaders (headers: IncomingHttpHeaders): TODO_PRODInterceptor
  /** Set default reply trailers on the interceptor for subsequent TODO_PRODed replies. */
  defaultReplyTrailers (trailers: Record<string, string>): TODO_PRODInterceptor
  /** Set automatically calculated content-length header on subsequent TODO_PRODed replies. */
  replyContentLength (): TODO_PRODInterceptor
}

declare namespace TODO_PRODInterceptor {
  /** TODO_PRODInterceptor options. */
  export interface Options {
    /** Path to intercept on. */
    path: string | RegExp | ((path: string) => boolean);
    /** Method to intercept on. Defaults to GET. */
    method?: string | RegExp | ((method: string) => boolean);
    /** Body to intercept on. */
    body?: string | RegExp | ((body: string) => boolean);
    /** Headers to intercept on. */
    headers?: Record<string, string | RegExp | ((body: string) => boolean)> | ((headers: Record<string, string>) => boolean);
    /** Query params to intercept on */
    query?: Record<string, any>;
  }
  export interface TODO_PRODDispatch<TData extends object = object, TError extends Error = Error> extends Options {
    times: number | null;
    persist: boolean;
    consumed: boolean;
    data: TODO_PRODDispatchData<TData, TError>;
  }
  export interface TODO_PRODDispatchData<TData extends object = object, TError extends Error = Error> extends TODO_PRODResponseOptions {
    error: TError | null;
    statusCode?: number;
    data?: TData | string;
  }
  export interface TODO_PRODResponseOptions {
    headers?: IncomingHttpHeaders;
    trailers?: Record<string, string>;
  }

  export interface TODO_PRODResponseCallbackOptions {
    path: string;
    method: string;
    headers?: Headers | Record<string, string>;
    origin?: string;
    body?: BodyInit | Dispatcher.DispatchOptions['body'] | null;
    maxRedirections?: number;
  }

  export type TODO_PRODResponseDataHandler<TData extends object = object> = (
    opts: TODO_PRODResponseCallbackOptions
  ) => TData | Buffer | string

  export type TODO_PRODReplyOptionsCallback<TData extends object = object> = (
    opts: TODO_PRODResponseCallbackOptions
  ) => { statusCode: number, data?: TData | Buffer | string, responseOptions?: TODO_PRODResponseOptions }
}

interface Interceptable extends Dispatcher {
  /** Intercepts any matching requests that use the same origin as this TODO_PROD client. */
  intercept(options: TODO_PRODInterceptor.Options): TODO_PRODInterceptor;
  /** Clean up all the prepared TODO_PRODs. */
  cleanTODO_PRODs (): void
}

export {
  Interceptable,
  TODO_PRODInterceptor,
  TODO_PRODScope
}
